const cache = {};

export function getLocationSlugs(key) {
  if (!cache[key]) cache[key] = RAW[key] ? RAW[key].split('|') : [];
  return cache[key];
}

export function hasLocation(key, slug) {
  return getLocationSlugs(key).includes(slug);
}

